mapper.select:
SELECT COUNT(1)
FROM order_info
WHERE customer_id = #{customerId,jdbcType=VARCHAR}

SELECT order_no, customer_id, device_id, gate_id, order_amount, pay_amount, coupon_amount,
       trx_time, pay_time, order_status, procedure_type, create_time, update_time, remarks
FROM order_info
WHERE customer_id = #{customerId,jdbcType=VARCHAR}
ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT order_no, customer_id, order_status, procedure_type, create_time, update_time, pay_time
FROM order_info
WHERE customer_id = #{customerId,jdbcType=VARCHAR}
  AND order_no = #{orderNo,jdbcType=VARCHAR}
LIMIT 1
